// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {GameItems} from "../src/GameItems.sol";

interface IProbe165 {
    function supportsInterface(bytes4 interfaceId) external view returns (bool);
}

interface IProbe1155 {
    function balanceOf(address account, uint256 id) external view returns (uint256);
    function balanceOfBatch(address[] calldata accounts, uint256[] calldata ids) external view returns (uint256[] memory);
    function setApprovalForAll(address operator, bool approved) external;
    function isApprovedForAll(address account, address operator) external view returns (bool);
    function safeTransferFrom(address from, address to, uint256 id, uint256 amount, bytes calldata data) external;
    function safeBatchTransferFrom(address from, address to, uint256[] calldata ids, uint256[] calldata amounts, bytes calldata data) external;
}

interface IProbe1155Meta is IProbe1155 {
    function uri(uint256 id) external view returns (string memory);
}

contract InvMutTest is Test {
    GameItems c;

    function setUp() public { c = new GameItems(address(this), address(this)); }

    function testFuzz_property(uint256 pick, uint256 noise) public {
        // Rule: for every canonical ERC-165 interface id that C implements —
        // IERC165, IERC1155, or IERC1155MetadataURI — c.supportsInterface(id)
        // must report true. The ids are computed at runtime from interface
        // types, not hard-coded literals.
        bytes4 id165 = type(IProbe165).interfaceId;
        bytes4 id1155 = type(IProbe1155).interfaceId;
        bytes4 idMeta = type(IProbe1155Meta).interfaceId;

        uint256 which = pick % 3;
        bytes4 queried = which == 0 ? id165 : (which == 1 ? id1155 : idMeta);

        // Fuzzed noise must never overturn a canonical registration: the
        // contract's answer depends only on the queried id itself.
        bool ok;
        bytes4 sel = queried ^ bytes4(uint32(uint256(noise) % 2));
        if (sel == queried) {
            try c.supportsInterface(queried) returns (bool r) { ok = r; } catch { ok = false; }
        } else {
            try c.supportsInterface(queried) returns (bool r) { ok = r; } catch { ok = false; }
        }
        assertTrue(ok);
    }
}
